}

String _canonicalOperationForTechnology(String technology) {
  return switch (technology.trim().toLowerCase()) {
    'rotogravure' || 'flexographic' => 'print',
    'adhesive_lamination' || 'extrusion_lamination' => 'laminate',
    'slitting' => 'cut',
    'bag_making' => 'package',
    'cold_glue' => 'glue',
    _ => '',
  };
}

